def mat_pow(mat, power):
    # Initialize result as identity matrix
    result = [[1 if i == j else 0 for j in range(3)] for i in range(3)]
    while power:
        if power & 1:
            result = mat_mul(result, mat)
        mat = mat_mul(mat, mat)
        power >>= 1
    return result

